# INSTALL SA Academies Map prototype
# Run from: S:\WORK\Digititan mobile app
# ASCII-only
$ErrorActionPreference = "Stop"
if (-not (Test-Path ".\mobile\pubspec.yaml")) { Write-Error "Wrong folder. cd to S:\WORK\Digititan mobile app" }
$root = (Get-Location).Path
function Write-B64([string]$rel, [string]$b64) {
  $full = Join-Path $root $rel
  $dir = Split-Path $full -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($full, [Convert]::FromBase64String($b64))
  Write-Host "Wrote $rel"
}
Write-Host "=== Digititan: SA Academies Map ===" -ForegroundColor Cyan
Write-B64 "mobile\lib\domain\entities\academy.dart" @"

"@
Write-B64 "mobile\lib\infrastructure\dummy\dummy_academy_repository.dart" @"

"@
Write-B64 "mobile\lib\presentation\customer\widgets\south_africa_academies_map.dart" @"

"@
Write-B64 "mobile\lib\presentation\customer\tabs\academies_tab.dart" @"

"@
Write-B64 "mobile\lib\presentation\customer\academy_detail_screen.dart" @"

"@
Write-Host ""
Write-Host "SUCCESS - SA map + academy events/programmes/location installed." -ForegroundColor Green
Write-Host "Next:"
Write-Host '  cd "S:\WORK\Digititan mobile app\mobile"'
Write-Host "  flutter run -d emulator-5554"
